-- mod-temucraft-lostlands: OPTIONAL spawns on Eastern Kingdoms and Kalimdor. They were placed on the reference world terrain, which differs from Open Azeroth in the new zones, so many will float or sit underground. Run only if you want them, then check them in game.
-- 16825 creatures, 19149 objects. Re-runnable.
SET @CRE := 1200000; SET @GO := 1200000;
SET @GUID_CRE := 5000000; SET @GUID_GO := 5000000;
DELETE FROM `creature` WHERE `guid` BETWEEN @GUID_CRE+4973 AND @GUID_CRE+21797;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN @GUID_CRE+4973 AND @GUID_CRE+21797;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN (@GUID_CRE+4973)*10 AND (@GUID_CRE+21797)*10+9;
DELETE FROM `gameobject` WHERE `guid` BETWEEN @GUID_GO+1666 AND @GUID_GO+20814;
